func (this *CTabFolder) _findMnemonic(string_ string) uint16 {
	if string_ == "" {
		return '\u0000'
	}
	var index int32 = 0
	var length int32 = jrt.StringLength(string_)
	for {
		for index < length && int32(utf16.Encode([]rune(string_))[index]) != int32('&') {
			index++
		}
		index++
		if index >= length {
			return '\u0000'
		}
		if int32(utf16.Encode([]rune(string_))[index]) != int32('&') {
			return uint16(unicode.ToLower(rune(utf16.Encode([]rune(string_))[index])))
		}
		index++
		if !(index < length) {
			break
		}
	}
	return '\u0000'
}

func (this *CTabFolder) StripMnemonic(string_ string) string {
	var index int32 = 0
	var length int32 = jrt.StringLength(string_)
	for {
		for (index < length) && (int32(utf16.Encode([]rune(string_))[index]) != int32('&')) {
			index++
		}
		index++
		if index >= length {
			return string_
		}
		if int32(utf16.Encode([]rune(string_))[index]) != int32('&') {
			return fmt.Sprintf("%s%s", jrt.Substring(string_, 0, index-1), jrt.Substring(string_, index, length))
		}
		index++
		if !(index < length) {
			break
		}
	}
	return string_
}

