func (this *CTabFolder) OnKeyDown(eventLike EventLike) {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	this.RunUpdate()
	switch event.KeyCode {
	case ARROW_LEFT, ARROW_RIGHT:
		var count int32 = int32(len(this.items))
		if count == 0 {
			return
		}
		if this.selectedIndex == -1 {
			return
		}
		var leadKey int32
		if (this.impl.getStyle_() & RIGHT_TO_LEFT) != 0 {
			leadKey = ARROW_RIGHT
		} else {
			leadKey = ARROW_LEFT
		}
		var offset int32
		if event.KeyCode == leadKey {
			offset = -1
		} else {
			offset = 1
		}
		var index int32
		if !this.mru {
			index = this.selectedIndex + offset
		} else {
			var visible []int32 = make([]int32, int32(len(this.items)))
			var idx int32 = 0
			var current int32 = -1
			for i := int32(0); i < int32(len(this.items)); i++ {
				if this.items[i].showing {
					if i == this.selectedIndex {
						current = idx
					}
					t713 := idx
					idx++
					visible[t713] = i
				}
			}
			if current+offset >= 0 && current+offset < idx {
				index = visible[current+offset]
			} else {
				if this.showChevron {
					var chevronRect *Rectangle = this.chevronItem.GetBounds()
					chevronRect = event.Display.MapFromToRectangle(upcastToolBarToControl(this.chevronTb), upcastCTabFolderToControl(this), chevronRect)
					var e *CTabFolderEvent = newCTabFolderEvent(upcastCTabFolderToWidget(this))
					e.Time = event.Time
					e.X = chevronRect.X
					e.Y = chevronRect.Y
					e.Width = chevronRect.Width
					e.Height = chevronRect.Height
					e.Doit = true
					for _, folderListener := range this.folderListeners {
						folderListener.ShowList(e)
					}
					if e.Doit && !this.IsDisposed() {
						this.ShowList(chevronRect)
					}
				}
				return
			}
		}
		if index < 0 || index >= count {
			return
		}
		this.SetSelectionIndexNotify(index, true)
		this.ForceFocus()
	}
}

