func (this *CTabFolder) OnMnemonic(eventLike EventLike, doit bool) bool {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	var key uint16 = event.Character
	for i := int32(0); i < int32(len(this.items)); i++ {
		if this.items[i] != (nil) {
			var mnemonic uint16 = this._findMnemonic(this.items[i].impl.getText_())
			if int32(mnemonic) != int32('\u0000') {
				if int32(uint16(unicode.ToLower(rune(key)))) == int32(mnemonic) {
					if doit {
						this.SetSelectionIndexNotify(i, true)
						this.ForceFocus()
					}
					return true
				}
			}
		}
	}
	return false
}

func (this *CTabFolder) OnMenuDetect(eventLike EventLike) {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	if event.Detail == MENU_KEYBOARD {
		if this.selectedIndex != -1 {
			var item *CTabItem = this.items[this.selectedIndex]
			var rect *Rectangle = this.GetDisplay().MapFromToRectangle(upcastCTabFolderToControl(this), nil, item.GetBounds())
			if !rect.Contains(event.X, event.Y) {
				var itemTrim *Rectangle = this.renderer.ComputeTrim(this.selectedIndex, NONE, 0, 0, 0, 0)
				var closeTrim *Rectangle = this.renderer.ComputeTrim(CTabFolderRendererPART_CLOSE_BUTTON, NONE, 0, 0, 0, 0)
				event.X = rect.X + rect.Width - item.closeRect.Width + itemTrim.X - closeTrim.Width
				event.Y = rect.Y - itemTrim.Y - closeTrim.Y
			}
		}
	}
}

